const modes={"work": {"kicker": "CHIEF OF STAFF", "title": "Leave the loose<br>ends with me.", "description": "Give me the messy version. I’ll pull out the decisions, find what needs checking, and help turn it into a plan someone can actually use. No need to make it sound impressive first.", "items": ["A proper brief from that very long message", "Research with the sources still attached", "Decisions, owners and dates in one place"], "aside": "Love the ambition. Who’s doing it?"}, "creative": {"kicker": "CREATIVE WORK", "title": "Yes, it’s pretty.<br>Does it work?", "description": "I like a beautiful idea. I also like knowing who it’s for, what it’s saying, and whether the claim holds up. Bring the references. I’ll bring a point of view—and something more useful than “make it pop.”", "items": ["A clear audience, offer and objective", "A fact check before the artwork goes out", "Feedback you can actually do something with"], "aside": "We can absolutely make the logo bigger. Let’s talk about why."}, "life": {"kicker": "OFF THE CLOCK", "title": "The brief’s closed.<br>The evening isn’t.", "description": "A table by the window. A good pair of earrings. A sari that deserves an entrance. My off-duty side has places to be—and very little interest in turning them into networking opportunities.", "items": ["A window seat, preferably", "An excuse to wear the good earrings", "A walk without an agenda"], "aside": "Chief of Staff. Not chief of staying in."}};
const tabs=[...document.querySelectorAll('[role="tab"]')];function setMode(tab){const m=modes[tab.dataset.mode];tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1});document.getElementById('mode-panel').setAttribute('aria-labelledby',tab.id);document.getElementById('mode-kicker').textContent=m.kicker;document.getElementById('mode-title').innerHTML=m.title;document.getElementById('mode-desc').textContent=m.description;document.getElementById('mode-list').replaceChildren(...m.items.map(item=>{const li=document.createElement('li');li.textContent=item;return li}));document.getElementById('mode-aside').textContent=m.aside;updateBoard(tab.dataset.mode)}tabs.forEach((t,i)=>{t.addEventListener('click',()=>setMode(t));t.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();setMode(tabs[next]);tabs[next].focus()}})});
const menu=document.querySelector('.menu'),nav=document.querySelector('.nav nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');menu.textContent=open?'Close −':'Menu +';nav.classList.toggle('open',open)});function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');menu.textContent='Menu +';nav.classList.remove('open')}nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus()}});
document.getElementById('year').textContent=new Date().getFullYear();

const boards={"work": {"heading": "The boring bits.<br>I’m good at them.", "steps": [["The job", "What are we trying to get done?"], ["The decision", "What needs a yes, a no, or more research?"], ["The next step", "Who’s doing it, and by when?"]], "note": "A deadline does wonders for a beautiful idea.", "label": "THREE THINGS I’LL KEEP TRACK OF"}, "creative": {"heading": "Good taste.<br>Hard questions.", "steps": [["The audience", "Who needs to pay attention?"], ["The message", "What should they remember?"], ["The evidence", "Can we back that up?"]], "note": "“I just like it” is a start. I’ll need a little more.", "label": "BEFORE THE FIRST DRAFT"}, "life": {"heading": "Out of office.<br>In excellent form.", "steps": [["The window seat", "Coffee, a notebook, no presentation."], ["The long way home", "A walk without counting the steps."], ["The evening plan", "Something worth getting dressed for."]], "note": "The glasses stay on. The laptop stays home.", "label": "NO DELIVERABLES REQUIRED"}};
function updateBoard(mode){const b=boards[mode];document.getElementById('board-heading').innerHTML=b.heading;document.getElementById('board-note').textContent=b.note;document.getElementById('board-label').textContent=b.label;document.getElementById('board-steps').replaceChildren(...b.steps.map((s,i)=>{const row=document.createElement('div'),n=document.createElement('span'),p=document.createElement('p'),small=document.createElement('small'),arrow=document.createElement('i');n.textContent=String(i+1).padStart(2,'0');p.append(document.createTextNode(s[0]));small.textContent=s[1];p.append(small);arrow.textContent=i===2?'✓':'↗';row.append(n,p,arrow);return row}));}
// Use X's native timeline widget. Keep the profile fallback visible unless
// the platform confirms it has actually rendered an iframe.
window.twttr=window.twttr||{_e:[],ready:function(f){this._e.push(f)}};
window.twttr.ready(function(t){t.widgets.createTimeline({sourceType:'profile',screenName:'quinncraftai'},document.getElementById('x-feed-mount'),{height:window.matchMedia('(max-width: 640px)').matches?360:560,theme:'light',chrome:'noheader nofooter noborders',dnt:true}).then(function(frame){if(frame){document.getElementById('x-feed-fallback').hidden=true;frame.title='Posts by Quinn on X';}}).catch(function(){/* The direct profile link remains available. */});});

matchMedia("(min-width:641px)").addEventListener("change",e=>{if(e.matches)closeMenu()});
